//! ProUpServTx and ProUpRevTx transactions from base-sdk's crafted corpus
//! (`pkgs/primitives/corpus/payload_core.json5` at de0d0c7e), whose payload Core v24.0.0-rc.3
//! reads under both BLS flags or refuses under both. A refused payload adds no element; one Core
//! reads adds its ProTx hash (the operator payout script of these rows is empty).

use dash_core_vectors::hex::parse_hex;
use dash_filters::FilterQuery;
use dash_filters::elements::add_special_tx_elements;
use dash_primitives::Transaction;
use dash_types::codec::BaseCodec as _;

/// The rows whose payload Core refuses under both flags.
const REFUSED: [&str; 4] = [
    "",
    "",
    "",
    "",
];

/// The rows whose payload Core reads under both flags, the same transactions otherwise.
const READ: [&str; 8] = [
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
];

fn elements_of(raw: &str) -> FilterQuery {
    let tx = Transaction::decode(&mut parse_hex(raw).as_slice()).unwrap();
    let mut set = FilterQuery::new();
    add_special_tx_elements(&mut set, &tx);
    set
}

#[test]
fn refused_provider_updates_add_nothing() {
    let adding: Vec<usize> =
        (0..REFUSED.len()).filter(|&i| !elements_of(REFUSED[i]).is_empty()).collect();
    assert!(adding.is_empty(), "rows {adding:?} of REFUSED add elements");
}

#[test]
fn read_provider_updates_add_their_pro_tx_hash() {
    let mut expected = FilterQuery::new();
    expected.push(&[0x09; 32]);
    for raw in READ {
        assert_eq!(elements_of(raw), expected, "{raw}");
    }
}
